var qb = require('../common/quotaCircuitBreaker.js');

function show(name, text) {
    var cls = qb.classifyFailure(text);
    print(name + ' => ' + (cls ? cls.kind + ' provider=' + cls.provider + ' window=' + cls.window : 'null'));
}

// 1. the live line embedded in a leg-shaped blob (classifyInterruptedText concat shape)
show('blob', 'error: rate limit: the provider quota window is exhausted (zai/glm-5.3-flash) — wait it out or switch provider/model\n## Session summary\nthe CLI died');
// 2. mixed: chain outage 500s + the fa quota line for the LAST model
show('mixed-500+fa-quota', 'zai/glm-5.3-flash returned 500 (attempt 1/6)\nkimi-for-coding: error: rate limit: the provider quota window is exhausted (kimi/kimi-for-coding) — wait it out\nProvider chain exhausted: 2 of 2 chain model(s) failed');
// 3. window shape without any slash paren — provider must stay null
show('403-window', 'z.ai glm-5.3-flash answered 403 "weekly (7-day) usage limit" after 9 retries');
// 4. bare chain tail alone — must stay NOT quota
show('bare-chain', 'Provider chain exhausted: 2 of 2 chain model(s) failed after 6 attempt(s)');
// 5. the word "quota" alone (weak vocabulary, no exhausted-window phrasing) — bare 429 blip keeps gh-742 reset
show('429+quota-word', 'HTTP 429: quota rate limit exceeded, retry in 30s');
// 6. empty/garbage
show('empty', '');
show('garbage', 'some generic crash');
// 7. CRLF-normalized live line
show('crlf', 'error: rate limit: the provider quota window is exhausted (zai/glm-5.3-flash) — wait it out or switch provider/model\r\n');

